scripts.source:
// Racer quad: lift off, climb to 10 m and hover over the start point, upright, in gusty wind.
// Outputs: Motor FL / FR / RL / RR (one per prop; FL+RR spin CW, FR+RL spin CCW).
// The controller is a flight-controller-style cascade with a fixed motor mixer; evolution tunes its 8 gains.
// The mixer signs were measured on the craft: more front thrust = pitch up, more left (-z) thrust = roll right-up,
// more CW-pair thrust = negative yaw rate (canted motors), so every gain is >= 0.
// Reward terms (same shape as hover-pid.json):
//   height - always-on penalty for height error (capped at 20 m)
//   hover  - seconds within +-1 m of 10 m and 1.5 m horizontally (the headline number)
//   calm   - penalty for vertical speed (weighted more near the target)
//   drift  - penalty for horizontal distance from the start point
//   upright- penalty for tilt
//   spin   - penalty for yaw rate
//   crash  - one-off penalty (crash, tipped over or flew away above 30 m)
function terms() { return ["height", "hover", "calm", "drift", "upright", "spin", "crash"]; }

function reward(ctx) {
  const i = ctx.in, dt = ctx.dt;
  const dy = Math.abs(i["target.dy"]);
  const dh = Math.sqrt(i["target.dx"] * i["target.dx"] + i["target.dz"] * i["target.dz"]);
  const tilt = Math.min(Math.sqrt(i["att.pitch"] * i["att.pitch"] + i["att.roll"] * i["att.roll"]) / 90, 1);
  const near = dy < 3 ? 1 : 0.3;
  return {
    height: -Math.min(dy, 20) / 10 * dt,
    hover: (dy < 1 && dh < 1.5) ? dt : 0,
    calm: -Math.min(Math.abs(i.vs) / 5, 1) * near * dt * 0.5,
    drift: -Math.min(dh / 10, 1) * dt * 0.5,
    upright: -tilt * dt,
    spin: -Math.min(Math.abs(i["rate.yaw"]) / 180, 1) * dt * 0.3,
  };
}

function failed(ctx) {
  const i = ctx.in;
  return ctx.state.crashed || Math.abs(i["att.pitch"]) > 80 || Math.abs(i["att.roll"]) > 80 || i.alt > 30;
}
function terminate(ctx) { return failed(ctx); }

function fitness(ctx) {
  // The rest of the episode costs about what sitting on the ground costs (height error ~1/s).
  const crash = failed(ctx) ? -1.0 * (ctx.info.duration - ctx.t) - 1 : 0;
  const s = ctx.sum;
  return { fitness: s.height + s.hover + s.calm + s.drift + s.upright + s.spin + crash, terms: { crash: crash } };
}

function descriptor(ctx) { return [ctx.in["target.dx"], ctx.in["target.dz"]]; }

// --- Controller genes (8). Starting values fly, but badly (sluggish climb, wobbly, drifts in the wind).
function genome(base) {
  const g = (name, lo, hi, init) => base.genes.push({ name: name, group: "script", min: lo, max: hi, initial: init, sigma: (hi - lo) / 10 });
  g("hover", 0.05, 0.2, 0.08);      // thrust fraction that balances weight (true value ~0.106)
  g("kAlt", 0, 0.1, 0.01);          // thrust per m of height error
  g("kVs", 0, 0.1, 0.01);           // thrust per m/s of climb rate (damping)
  g("kAtt", 0, 0.01, 0.002);        // differential thrust per deg of attitude error
  g("kRate", 0, 0.003, 0.0002);     // differential thrust per deg/s of body rate
  g("kPos", 0, 5, 0.3);             // deg of lean per m of position error
  g("kVel", 0, 10, 0.5);            // deg of lean per m/s of ground speed (braking)
  g("kYaw", 0, 0.006, 0.0005);      // differential pair thrust per deg/s of yaw rate
  return base;
}

function control(ctx) {
  const G = ctx.genome, i = ctx.in;
  quad(ctx, {
    hover: G.get("hover"), kAlt: G.get("kAlt"), kVs: G.get("kVs"), kAtt: G.get("kAtt"), kRate: G.get("kRate"),
    kPos: G.get("kPos"), kVel: G.get("kVel"), kYaw: G.get("kYaw"), tiltMax: 30,
  }, { dx: i["target.dx"], dy: i["target.dy"], dz: i["target.dz"] }, 0);
}

// --- Quad flight controller (shared by drone-hover / drone-race). Cascade: position -> lean angle -> attitude PD
//     -> motor mixer, plus altitude PD and yaw-rate damping, all in thrust-fraction units (0..1 of static thrust).
//     tgt = offset to the goal (m, world axes); yawSp = yaw-rate setpoint (deg/s).
function quad(ctx, G, tgt, yawSp) {
  const i = ctx.in, m = ctx.memory, dt = ctx.dt;
  const dx = tgt.dx, dy = tgt.dy, dz = tgt.dz;
  // ground velocity from the rate of change of the target offset (there is no velocity sensor), lightly filtered
  const vx = m.pdx === undefined ? 0 : -(dx - m.pdx) / dt, vz = m.pdz === undefined ? 0 : -(dz - m.pdz) / dt;
  m.vx = m.vx === undefined ? 0 : m.vx + (vx - m.vx) * 0.3; m.vz = m.vz === undefined ? 0 : m.vz + (vz - m.vz) * 0.3;
  m.pdx = dx; m.pdz = dz;
  const lim = G.tiltMax;
  const pitchSp = clamp(-(G.kPos * dx - G.kVel * m.vx), -lim, lim);   // nose down to go +x
  const rollSp = clamp(G.kPos * dz - G.kVel * m.vz, -lim, lim);       // roll positive to go +z
  const tilt = Math.min(Math.sqrt(i["att.pitch"] * i["att.pitch"] + i["att.roll"] * i["att.roll"]), 80) * Math.PI / 180;
  const f = (G.hover + G.kAlt * clamp(dy, -10, 10) - G.kVs * i.vs) / Math.max(Math.cos(tilt), 0.3);   // tilt compensation
  const p = G.kAtt * (pitchSp - i["att.pitch"]) - G.kRate * i["rate.pitch"];
  const r = G.kAtt * (rollSp - i["att.roll"]) - G.kRate * i["rate.roll"];
  const y = -G.kYaw * (i["rate.yaw"] - (yawSp || 0));   // speeding up the CW pair (FL, RR) yaws the body to negative rate
  const e = (v) => Math.pow(clamp(v, 0, 1), 1.5);   // thrust fraction -> motor command (static thrust ~ power^2/3)
  ctx.out["Motor FL"] = e(f + p + r + y);
  ctx.out["Motor FR"] = e(f + p - r - y);
  ctx.out["Motor RL"] = e(f - p + r - y);
  ctx.out["Motor RR"] = e(f - p - r + y);
}
